using namespace std;

class Solution {
public:
    int numberOfComponents(vector<vector<int>>& properties, int k) {
        int n = properties.size();
        vector<unordered_set<int>> sets(n);
        for (int i = 0; i < n; ++i) {
            sets[i] = unordered_set<int>(properties[i].begin(), properties[i].end());
        }

        vector<vector<int>> adj(n);
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int common = 0;
                for (int x : sets[i]) {
                    if (sets[j].count(x)) common++;
                }
                if (common >= k) {
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
            }
        }

        vector<bool> visited(n, false);
        int components = 0;

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                components++;
                visited[i] = true;
                vector<int> stack = {i};
                while (!stack.empty()) {
                    int curr = stack.back();
                    stack.pop_back();
                    for (int nxt : adj[curr]) {
                        if (!visited[nxt]) {
                            visited[nxt] = true;
                            stack.push_back(nxt);
                        }
                    }
                }
            }
        }

        return components;
    }
};

import java.util.*;

class Solution {
    public int numberOfComponents(int[][] properties, int k) {
        int n = properties.length;
        List<Set<Integer>> sets = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Set<Integer> s = new HashSet<>();
            for (int x : properties[i]) s.add(x);
            sets.add(s);
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int common = 0;
                for (int x : sets.get(i)) {
                    if (sets.get(j).contains(x)) common++;
                }
                if (common >= k) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
            }
        }

        boolean[] visited = new boolean[n];
        int components = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                components++;
                visited[i] = true;
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(i);
                while (!stack.isEmpty()) {
                    int curr = stack.pop();
                    for (int nxt : adj.get(curr)) {
                        if (!visited[nxt]) {
                            visited[nxt] = true;
                            stack.push(nxt);
                        }
                    }
                }
            }
        }

        return components;
    }
}

var numberOfComponents = function(properties, k) {
    const n = properties.length;
    const sets = properties.map(p => new Set(p));
    const adj = Array.from({ length: n }, () => []);

    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            let common = 0;
            for (const x of sets[i]) {
                if (sets[j].has(x)) common++;
            }
            if (common >= k) {
                adj[i].push(j);
                adj[j].push(i);
            }
        }
    }

    const visited = new Array(n).fill(false);
    let components = 0;

    for (let i = 0; i < n; i++) {
        if (!visited[i]) {
            components++;
            visited[i] = true;
            const stack = [i];
            while (stack.length > 0) {
                const curr = stack.pop();
                for (const nxt of adj[curr]) {
                    if (!visited[nxt]) {
                        visited[nxt] = true;
                        stack.push(nxt);
                    }
                }
            }
        }
    }

    return components;
};
